{
  "info": {
    "title": "UAE Payment API",
    "description": "## UAE Open Finance Payment API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/payment/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/payment/v2.1"
    }
  ],
  "source_path": "/payments",
  "operations": {
    "post": {
      "tags": [
        "Payment Initiation"
      ],
      "summary": "Create a Payment",
      "description": "Create a Payment\n",
      "operationId": "CreatePayment",
      "parameters": [
        {
          "$ref": "#/components/parameters/authorization"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id-request"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-idempotency-key"
        },
        {
          "$ref": "#/components/parameters/x-consent-id"
        }
      ],
      "requestBody": {
        "description": "Request Body\n",
        "content": {
          "application/jwt": {
            "schema": {
              "$ref": "#/components/schemas/AEPaymentRequestSigned"
            }
          }
        }
      },
      "responses": {
        "201": {
          "$ref": "#/components/responses/201PaymentId"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "409": {
          "$ref": "#/components/responses/409Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "payments"
          ]
        }
      ]
    }
  }
}

{
  "in": "header",
  "name": "authorization",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  },
  "example": "Bearer 12773da5-81c5-45e7-893c-381ca3cecc30"
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2023 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  },
  "example": "Thu, 26 Jan 2023 16:31:32 UTC"
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  },
  "example": "51.235.115.203"
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  },
  "example": "Mozilla/5.0 (iPhone; CPU iPhone OS 10_3_1 like Mac OS X) AppleWebKit/603.1.30 (KHTML, like Gecko) Version/10.0 Mobile/14E304 Safari/602.1"
}

{
  "name": "x-idempotency-key",
  "in": "header",
  "description": "Ensures the LFI processes the resource successfully only once per x-idempotency-key\n\nThe TPP must not change the request body while using the same x-idempotency-key, changes to the request body \nwill not result any action on the end resource. \n\nThe OFP will treat a request as idempotent if it had received the first request with the same x-idempotency-key \nfrom the same TPP in the preceding 24 hours.\n",
  "required": true,
  "schema": {
    "type": "string",
    "maxLength": 40,
    "pattern": "^(\\S*)$"
  },
  "example": "78dae4513b8847f98e2d4173b4ed0eb6"
}

{
  "name": "x-consent-id",
  "in": "header",
  "description": "The Consent ID relating to the Payment Initiation Request, required where a given payment instruction is part of a Combined Consent Group to ensure the payment is correctly executed against the correct consent. TPPs must replay the value they assigned to the consent in the Rich Authorization Request.",
  "required": false,
  "schema": {
    "type": "string",
    "format": "uuid"
  }
}

{
  "description": "Payment Request Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/AEJwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEPaymentRequest"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "[https://www.rfc-editor.org/rfc/rfc7519](https://www.rfc-editor.org/rfc/rfc7519)\n",
  "type": "object",
  "properties": {
    "iss": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)\n",
      "type": "string"
    },
    "exp": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)\n",
      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\n",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "iat": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)\n",
      "type": "number"
    }
  },
  "required": [
    "iss",
    "exp",
    "nbf"
  ]
}

{
  "description": "Payment Request Schema\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Data"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ConsentId",
        "Instruction",
        "PaymentPurposeCode",
        "OpenFinanceBilling"
      ],
      "properties": {
        "ConsentId": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentId"
        },
        "Instruction": {
          "$ref": "#/components/schemas/AEPaymentInstruction"
        },
        "CurrencyRequest": {
          "$ref": "#/components/schemas/AECurrencyRequest"
        },
        "PersonalIdentifiableInformation": {
          "description": "Personal Identifiable Information, represented in both encoded and decoded form using a `anyOf`, to help implementers readily understand both the structure and serialized form of the property. Schema Objects are provided for both Domestic and International payments.\n\n**Implementations MUST reflect the AEJWEPaymentPII Schema Object structure and the notes provided on** **implementing a JWS and JWE.**\n\n**The decoded form AEPaymentPII is for guidance on content only.**",
          "anyOf": [
            {
              "$ref": "#/components/schemas/AEBankServiceInitiation.AEDomesticPaymentPIIProperties"
            },
            {
              "$ref": "#/components/schemas/AEBankServiceInitiation.AEInternationalPaymentPIIProperties"
            },
            {
              "$ref": "#/components/schemas/AEJWEPaymentPII"
            }
          ]
        },
        "PaymentPurposeCode": {
          "$ref": "#/components/schemas/AEPaymentPurposeCode"
        },
        "DebtorReference": {
          "$ref": "#/components/schemas/AEDebtorReference"
        },
        "CreditorReference": {
          "$ref": "#/components/schemas/AECreditorReference"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBilling"
        }
      }
    }
  }
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "Unique identification assigned by the TPP to identify the consent resource."
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Amount"
  ],
  "description": "The Initiation payload is sent by the initiating party to the LFI. It is used to request movement of funds from the debtor account to a creditor for a single payment.",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAmount"
    }
  }
}

{
  "description": "The Currency and Amount relating to the Payment\n",
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricAmount"
    },
    "Currency": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyCode"
    }
  }
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "example": "100.00"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "description": "The details of the non-local currency or FX request that has been agreed between the User and the TPP.\nThe requested ChargeBearer and ExchangeRateInformation are included in this object may be overwritten by the LFI in the returned Consent object.\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "ExtendedPurpose",
    "CurrencyOfTransfer"
  ],
  "properties": {
    "InstructionPriority": {
      "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction.",
      "type": "string",
      "enum": [
        "Normal",
        "Urgent"
      ]
    },
    "ExtendedPurpose": {
      "description": "Specifies the purpose of an international payment.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "ChargeBearer": {
      "$ref": "#/components/schemas/AEChargeBearerType1Code"
    },
    "CurrencyOfTransfer": {
      "description": "Specifies the currency of the to be transferred amount, which is different from the currency of the debtor's account.",
      "type": "string",
      "pattern": "^[A-Z]{3,3}$"
    },
    "DestinationCountryCode": {
      "description": "Country in which Credit Account is domiciled. Code to identify a country, a dependency, or another area of particular geopolitical interest, on the basis of country names obtained from the United Nations (ISO 3166, Alpha-2 code).",
      "type": "string",
      "pattern": "[A-Z]{2,2}"
    },
    "ExchangeRateInformation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "UnitCurrency",
        "RateType"
      ],
      "description": "Provides details on the currency exchange rate and contract.",
      "properties": {
        "UnitCurrency": {
          "description": "Currency in which the rate of exchange is expressed in a currency exchange. In the example 1GBP = xxxCUR, the unit currency is GBP.",
          "type": "string",
          "pattern": "^[A-Z]{3,3}$"
        },
        "ExchangeRate": {
          "description": "The factor used for conversion of an amount from one currency to another. This reflects the price at which one currency was bought with another currency.",
          "type": "number"
        },
        "RateType": {
          "description": "Specifies the type used to complete the currency exchange.",
          "type": "string",
          "enum": [
            "Actual",
            "Agreed",
            "Indicative"
          ]
        },
        "ContractIdentification": {
          "description": "Unique and unambiguous reference to the foreign exchange contract agreed between the initiating party/creditor and the debtor agent.",
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        }
      }
    },
    "FxQuoteId": {
      "description": "Required where the consent or payment initiation request relates to a previously quoted FX trade. The TPP must provide the `QuoteId` value where a long-lived consent exists, meaning that each payment initiation request will relate to a different `QuoteId` value.",
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    }
  }
}

{
  "description": "Specifies which party/parties will bear the charges associated with the processing of the payment transaction.",
  "type": "string",
  "enum": [
    "BorneByCreditor",
    "BorneByDebtor",
    "Shared"
  ]
}

{
  "title": "Domestic Payment PII Schema Object",
  "type": "object",
  "additionalProperties": false,
  "description": "Elements of Personal Identifiable Information data",
  "properties": {
    "Initiation": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticCreditor"
    },
    "Risk": {
      "$ref": "#/components/schemas/AERisk"
    }
  }
}

{
  "type": "object",
  "required": [
    "CreditorAccount"
  ],
  "properties": {
    "CreditorAgent": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorAgentProperties"
    },
    "Creditor": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorProperties"
    },
    "CreditorAccount": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticCreditorAccountProperties"
    },
    "ConfirmationOfPayeeResponse": {
      "type": "string",
      "pattern": "^.+\\..+\\..+$",
      "description": "Response from Confirmation of Payee operation, when executed for the Creditor Account.\n\nThis is JSON Web Signature returned by the Payee Confirmation operation at the Confirmation of Payee API.\n\nThe value must be the full JWS string, including the header and signature, without decoding to an object.\n\nIf Confirmation of Payee is not performed this property can be omitted"
    }
  },
  "description": "Identification elements for a Creditor for a domestic payment instruction.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "description": "The identification scheme for uniquely identifying the Agent.\n* BICFI: The BIC/SWIFT Code\n* Other: Identifier based on non-SWIFT payment system or local market scheme.\n",
      "enum": [
        "BICFI",
        "Other"
      ]
    },
    "Identification": {
      "description": "Identifier that can be the BIC/SWIFT code or target payment scheme identifier.",
      "type": "string"
    },
    "Name": {
      "description": "Name by which an agent is known and which is usually used to identify that agent.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostalAddress": {
      "$ref": "#/components/schemas/AEAddress"
    }
  },
  "description": "Properties of the Creditor Agent, which provides information on the Financial Institution that holds the Creditor Account.",
  "additionalProperties": false
}

{
  "description": "One-or-more addresses related to a given subject.",
  "type": "array",
  "minItems": 1,
  "items": {
    "description": "Address properties based on ISO 20022 `PostalAddress27` definition",
    "type": "object",
    "required": [
      "AddressType",
      "AddressLine",
      "Country"
    ],
    "properties": {
      "AddressType": {
        "description": "The type of address.",
        "type": "string",
        "enum": [
          "Billing",
          "Business",
          "Correspondence",
          "DeliveryTo",
          "MailTo",
          "POBox",
          "Postal",
          "Permanent",
          "Residential",
          "Statement",
          "Other"
        ]
      },
      "AddressLine": {
        "description": "Information that locates and identifies a specific address for a transaction entry, that is presented in free format text.",
        "type": "array",
        "minItems": 1,
        "maxItems": 7,
        "items": {
          "type": "string",
          "minLength": 1,
          "maxLength": 70
        }
      },
      "BuildingNumber": {
        "description": "The unit, apartment, or villa number within a building or community",
        "type": "string",
        "minLength": 1,
        "maxLength": 16
      },
      "BuildingName": {
        "description": "Name of the building or house.",
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      },
      "Floor": {
        "description": "Floor or storey within a building.",
        "type": "string",
        "minLength": 1,
        "maxLength": 70
      },
      "StreetName": {
        "description": "The name of the street or road where the property is located.",
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      },
      "DistrictName": {
        "description": "The district, community, or neighbourhood where the property is located.",
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      },
      "PostBox": {
        "description": "The P.O. Box number assigned to the recipient for mail delivery.",
        "type": "string",
        "minLength": 1,
        "maxLength": 16
      },
      "TownName": {
        "description": "Name of a built-up area, such as a town or city.",
        "type": "string",
        "minLength": 1,
        "maxLength": 140
      },
      "CountrySubDivision": {
        "description": "Country subdivision, such as state or province. Where the address is in the UAE this is the Emirate where the address is registered.",
        "anyOf": [
          {
            "type": "string",
            "enum": [
              "AbuDhabi",
              "Ajman",
              "Dubai",
              "Fujairah",
              "RasAlKhaimah",
              "Sharjah",
              "UmmAlQuwain"
            ]
          },
          {
            "type": "string"
          }
        ]
      },
      "Country": {
        "description": "The country associated with the address, represented using the ISO 3166-1 alpha-2 country code.",
        "type": "string",
        "pattern": "^[A-Z]{2}$"
      }
    },
    "additionalProperties": false
  }
}

{
  "type": "object",
  "properties": {
    "Name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostalAddress": {
      "$ref": "#/components/schemas/AEAddress"
    }
  },
  "description": "Party to which an amount of money is due.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification",
    "Name"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "enum": [
        "IBAN"
      ],
      "description": "Domestic payment scheme, restricted to `IBAN`"
    },
    "Identification": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEIdentification"
    },
    "Name": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEName"
    },
    "TradingName": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AETradingName"
    },
    "Type": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorAccountTypeCodes"
    }
  },
  "description": "Unambiguous identification of the account of the creditor to which a credit entry will be posted.",
  "additionalProperties": false
}

{
  "type": "string",
  "minLength": 1,
  "description": "Identification for the account assigned by the LFI based on the Account Scheme Name.\nThis identification is known by the User account owner."
}

{
  "type": "object",
  "properties": {
    "en": {
      "type": "string",
      "maxLength": 70,
      "description": "English value of the string"
    },
    "ar": {
      "type": "string",
      "maxLength": 70,
      "description": "Arabic value of the string"
    }
  },
  "description": "The Account Holder Name is the name or names of the Account owner(s) represented at the account level",
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "en": {
      "type": "string",
      "maxLength": 70,
      "description": "English value of the string"
    },
    "ar": {
      "type": "string",
      "maxLength": 70,
      "description": "Arabic value of the string"
    }
  },
  "description": "The Trading Brand Name (if applicable) for the Creditor.\nApplicable to Payments.",
  "additionalProperties": false
}

{
  "additionalProperties": false,
  "description": "The Risk section is sent by the TPP to the LFI. It is used to specify additional details for risk/fraud scoring regarding Payments.\n",
  "type": "object",
  "properties": {
    "DebtorIndicators": {
      "$ref": "#/components/schemas/AEDebtorIndicators"
    },
    "DestinationDeliveryAddress": {
      "type": "object",
      "description": "Destination Delivery Address\n",
      "properties": {
        "RecipientType": {
          "type": "string",
          "description": "The recipient of the goods whether an individual or a corporation.",
          "enum": [
            "Individual",
            "Corporate"
          ]
        },
        "RecipientName": {
          "type": "object",
          "description": "The name of the recipient of the goods, whether an individual or a corporation.",
          "properties": {
            "en": {
              "type": "string",
              "description": "English value of the string"
            },
            "ar": {
              "type": "string",
              "description": "Arabic value of the string"
            }
          },
          "additionalProperties": false
        },
        "NationalAddress": {
          "$ref": "#/components/schemas/AEAddress"
        }
      },
      "additionalProperties": false
    },
    "TransactionIndicators": {
      "$ref": "#/components/schemas/AETransactionIndicators"
    },
    "CreditorIndicators": {
      "$ref": "#/components/schemas/AECreditorIndicators"
    }
  }
}

{
  "type": "object",
  "description": "Debtor (User) Indicators\n",
  "properties": {
    "Authentication": {
      "type": "object",
      "description": "The authentication method used by the User to access their account with the TPP",
      "properties": {
        "AuthenticationChannel": {
          "description": "Channel on which the User was authenticated",
          "type": "string",
          "enum": [
            "App",
            "Web"
          ]
        },
        "PossessionFactor": {
          "type": "object",
          "description": "The User's possession, that only the User possesses",
          "properties": {
            "IsUsed": {
              "type": "boolean"
            },
            "Type": {
              "type": "string",
              "enum": [
                "FIDO2SecurityKey",
                "Passkey",
                "OTPDevice",
                "OTPApp",
                "SMSOTP",
                "EmailOTP",
                "PushNotification",
                "WebauthnToken",
                "SecureEnclaveKey",
                "HardwareOTPKey",
                "TrustedDevice",
                "Other"
              ]
            }
          },
          "additionalProperties": false
        },
        "KnowledgeFactor": {
          "type": "object",
